-- Frozen copies of the workflows and approvals above (version 1, the way every create or edit freezes them). Frozen tables have no foreign keys.
INSERT IGNORE INTO `crm_frozen_approvals` (`id`,`source_approval_code`,`freeze_version`,`is_latest_freeze`,`name`,`approval_type`,`description`,`frozen_by_name`,`frozen_at`)
  SELECT UUID(),`code`,1,1,`name`,`approval_type`,`description`,'seed',CURRENT_TIMESTAMP(3) FROM `crm_master_approvals`;
INSERT IGNORE INTO `crm_frozen_approval_levels` (`id`,`freeze_id`,`level_no`,`app_id`,`authority_name`)
  SELECT UUID(),f.`id`,l.`level_no`,l.`app_id`,l.`authority_name` FROM `crm_master_approval_levels` l JOIN `crm_frozen_approvals` f ON f.`source_approval_code`=l.`approval_code` AND f.`is_latest_freeze`=1;
INSERT IGNORE INTO `crm_frozen_workflows` (`id`,`source_workflow_code`,`freeze_version`,`is_latest_freeze`,`name`,`description`,`frozen_by_name`,`frozen_at`)
  SELECT UUID(),`code`,1,1,`name`,`description`,'seed',CURRENT_TIMESTAMP(3) FROM `crm_workflows`;
INSERT IGNORE INTO `crm_frozen_workflow_stage_groups` (`id`,`freeze_id`,`code`,`name`,`sort_order`,`description`)
  SELECT UUID(),f.`id`,x.`code`,x.`name`,x.`sort_order`,x.`description` FROM `crm_workflow_stage_groups` x JOIN `crm_frozen_workflows` f ON f.`source_workflow_code`=x.`workflow_code` AND f.`is_latest_freeze`=1;
INSERT IGNORE INTO `crm_frozen_workflow_stages` (`id`,`freeze_id`,`group_code`,`code`,`name`,`department_code`,`sort_order`,`form_code`,`description`)
  SELECT UUID(),f.`id`,x.`group_code`,x.`code`,x.`name`,x.`department_code`,x.`sort_order`,x.`form_code`,x.`description` FROM `crm_workflow_stages` x JOIN `crm_frozen_workflows` f ON f.`source_workflow_code`=x.`workflow_code` AND f.`is_latest_freeze`=1;
INSERT IGNORE INTO `crm_frozen_workflow_stage_fields` (`id`,`freeze_id`,`stage_code`,`form_field_code`,`is_mandatory`)
  SELECT UUID(),f.`id`,x.`stage_code`,x.`form_field_code`,x.`is_mandatory` FROM `crm_workflow_stage_fields` x JOIN `crm_frozen_workflows` f ON f.`source_workflow_code`=x.`workflow_code` AND f.`is_latest_freeze`=1;
INSERT IGNORE INTO `crm_frozen_workflow_stage_documents` (`id`,`freeze_id`,`group_code`,`stage_code`,`document_type_id`,`document_code`,`is_default`,`is_mandatory`,`sort_order`)
  SELECT UUID(),f.`id`,x.`group_code`,x.`stage_code`,x.`document_type_id`,x.`document_code`,x.`is_default`,x.`is_mandatory`,x.`sort_order` FROM `crm_workflow_stage_documents` x JOIN `crm_frozen_workflows` f ON f.`source_workflow_code`=x.`workflow_code` AND f.`is_latest_freeze`=1;
INSERT IGNORE INTO `crm_frozen_workflow_approval_assignments` (`id`,`freeze_id`,`code`,`scope_type`,`section_code`,`group_code`,`stage_code`,`document_code`,`approval_code`,`approval_freeze_id`)
  SELECT UUID(),f.`id`,x.`code`,x.`scope_type`,x.`section_code`,x.`group_code`,x.`stage_code`,x.`document_code`,x.`approval_code`,a.`id` FROM `crm_workflow_approval_assignments` x
  JOIN `crm_frozen_workflows` f ON f.`source_workflow_code`=x.`workflow_code` AND f.`is_latest_freeze`=1
  JOIN `crm_frozen_approvals` a ON a.`source_approval_code`=x.`approval_code` AND a.`is_latest_freeze`=1;

